        if kind is None:
            raise CalcError("unexpected end of expression")
        raise CalcError("unexpected token: %r" % (value,))

    # -- grammar --------------------------------------------------------

    def parse(self):
        return self._additive()

    def _additive(self):
        value = self._multiplicative()
        while True:
            op = self._peek_op()
            if op == "+" or op == "-":
                self._advance()
                right = self._multiplicative()
                if op == "+":
                    value = value + right
                else:
                    value = value - right
            else:
                return value

    def _multiplicative(self):
        value = self._unary()
        while True:
            op = self._peek_op()
            if op in ("*", "/", "//", "%"):
                self._advance()
                right = self._unary()
                value = self._binary(op, value, right)
            else:
                return value

    def _unary(self):
        op = self._peek_op()
        if op == "+":
            self._advance()
            return +self._unary()
        if op == "-":
            self._advance()
            return -self._unary()
        return self._power()

