import random
from calc.core import evaluate, CalcError

random.seed(1234)

def atom(depth):
    r = random.random()
    if depth <= 0 or r < 0.4:
        return random.choice(["0", "1", "2", "3", "4", "5", "0.5", "1.5", ".5", "2.0", "3.25"])
    if r < 0.55:
        return random.choice(["x", "y"])
    if r < 0.8:
        fn = random.choice(["min", "max", "abs"])
        if fn == "abs":
            return "abs(%s)" % expr(depth - 1)
        return "%s(%s)" % (fn, ", ".join(expr(depth - 1) for _ in range(random.randint(1, 3))))
    return "(%s)" % expr(depth - 1)

def unary(depth):
    if depth > 0 and random.random() < 0.2:
        return random.choice(["-", "+", "--", "-+"]) + unary(depth - 1)
    return power(depth)

def power(depth):
    a = atom(depth - 1)
    # keep exponents small: only a literal or parenthesized tiny expression
    if depth > 0 and random.random() < 0.15:
        return a + "**" + random.choice(["0", "1", "2", "3", "-1", "-2", "0.5"])
    return a

def term(depth):
    s = unary(depth)
    for _ in range(random.randint(0, 2)):
        s += random.choice(["*", "/", "//", "%"]) + unary(depth - 1)
    return s

def expr(depth):
    s = term(depth)
    for _ in range(random.randint(0, 2)):
        s += random.choice(["+", "-"]) + term(depth - 1)
    return s

env = {"x": 3, "y": -2}
checked = 0
skipped = 0
for i in range(5000):
    e = expr(3)
    try:
        expected = eval(e, {"__builtins__": {}}, {"min": min, "max": max, "abs": abs, "x": 3, "y": -2})
    except Exception:
        skipped += 1
        continue
    if isinstance(expected, complex) or abs(expected) > 10**15:
        skipped += 1
        continue
    try:
        got = evaluate(e, env)
    except CalcError as exc:
        raise AssertionError("CalcError for valid %r: %s" % (e, exc))
    if got != expected or type(got) is not type(expected):
        raise AssertionError("mismatch %r: got %r (%s), expected %r (%s)"
                             % (e, got, type(got).__name__, expected, type(expected).__name__))
    checked += 1
print("fuzz passed on", checked, "expressions,", skipped, "skipped")
PY", "description": "Fuzz valid expressions with constrained exponents", "workdir": "<experiment>/runs/calc-standard-r3/workspace", "timeoutMs": 120000}

