from calc.core import evaluate
checks = {
    "1+2": int, "-2**2": int, "2**10": int, "7//2": int, "7%2": int,
    "-7//2": int, "1/2": float, "4/2": float, "2**-1": float,
    ".5+1": float, "min(1,2)": int, "max(1.0,2)": float, "abs(-3)": int,
}
for expr, typ in checks.items():
    got = evaluate(expr)
    assert type(got) is typ, (expr, got, type(got), typ)
print("type-preservation checks passed")
PY", "description": "Verify int/float result types", "workdir": "<experiment>/runs/calc-standard-r3/workspace"}

